"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import { api, ApiError } from "@/lib/api-client";
import { formatNaira } from "@/lib/mock-data";
import { FlashDealCountdown } from "@/components/flash-deal-countdown";
type Product={id:string;name:string;price:number|string;stock:number;status:string};
type Deal={id:string;productId:string;name:string;price:number;salePrice:number;discountPercent:number;startsAt:string;endsAt:string;active:boolean;paused?:boolean;quantityCap?:number|null;soldCount?:number;remaining?:number|null};
export default function FlashDealsPage(){const[products,setProducts]=useState<Product[]>([]);const[deals,setDeals]=useState<Deal[]>([]);const[productId,setProductId]=useState("");const[discount,setDiscount]=useState("20");const[endsAt,setEndsAt]=useState("");const[quantityCap,setQuantityCap]=useState("");const[busy,setBusy]=useState(false);const[error,setError]=useState<string|null>(null);
async function load(){const[p,d]=await Promise.all([api.get<{products?:Product[];items?:Product[]}>("/api/products/me/list"),api.get<{deals:Deal[]}>("/api/flash-deals/mine")]);setProducts(p.products??p.items??[]);setDeals(d.deals);}
useEffect(()=>{void load();},[]);
async function createDeal(e:React.FormEvent){e.preventDefault();setBusy(true);setError(null);try{const end=new Date(endsAt);if(!productId||!Number.isFinite(end.getTime())||end<=new Date())throw new Error("Choose a product and a future end time.");await api.post("/api/flash-deals/mine",{productId,discountPercent:Number(discount),startsAt:new Date().toISOString(),endsAt:end.toISOString(),quantityCap:quantityCap?Number(quantityCap):undefined});setProductId("");setDiscount("20");setEndsAt("");setQuantityCap("");await load();}catch(err){setError(err instanceof ApiError?err.message:err instanceof Error?err.message:"Could not create flash deal.");}finally{setBusy(false);}}
async function removeDeal(id:string){await api.delete(`/api/flash-deals/mine/${id}`);await load();}async function togglePause(deal:Deal){await api.patch(`/api/flash-deals/mine/${deal.id}/pause`,{paused:!deal.paused});await load();}
return <div className="shell py-8"><Link href="/vendor/dashboard" className="text-sm font-semibold text-ember-600">← Dashboard</Link><h1 className="mt-3 text-2xl font-bold text-graphite-900">Flash deals</h1><p className="mt-1 max-w-2xl text-sm text-graphite-600">Create limited-time discounts on eligible paid vendor plans. Add an optional inventory cap to automatically stop showing a deal after the cap is reached.</p>
<form onSubmit={createDeal} className="mt-6 grid gap-4 rounded-card border border-graphite-200 bg-white p-5 sm:grid-cols-5"><label className="text-sm sm:col-span-2"><span className="mb-1 block font-medium">Product</span><select value={productId} onChange={e=>setProductId(e.target.value)} required className="w-full rounded-[7px] border border-graphite-200 px-3 py-2"><option value="">Choose a product</option>{products.filter(p=>p.status==="ACTIVE"&&p.stock>0).map(p=><option key={p.id} value={p.id}>{p.name} — {formatNaira(Number(p.price))}</option>)}</select></label><label className="text-sm"><span className="mb-1 block font-medium">Discount %</span><input type="number" min="1" max="99" value={discount} onChange={e=>setDiscount(e.target.value)} required className="w-full rounded-[7px] border border-graphite-200 px-3 py-2"/></label><label className="text-sm"><span className="mb-1 block font-medium">Inventory cap</span><input type="number" min="1" value={quantityCap} onChange={e=>setQuantityCap(e.target.value)} placeholder="Optional" className="w-full rounded-[7px] border border-graphite-200 px-3 py-2"/></label><label className="text-sm"><span className="mb-1 block font-medium">Ends</span><input type="datetime-local" value={endsAt} onChange={e=>setEndsAt(e.target.value)} required className="w-full rounded-[7px] border border-graphite-200 px-3 py-2"/></label>{error&&<p className="sm:col-span-5 rounded-[7px] bg-ember-100 px-3 py-2 text-sm text-ember-700">{error}</p>}<button disabled={busy} className="sm:col-span-5 rounded-card bg-ember-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{busy?"Saving…":"Start flash deal"}</button></form>
<div className="mt-6 grid gap-3">{deals.map(deal=>{const sold=Number(deal.soldCount??0);const cap=deal.quantityCap==null?null:Number(deal.quantityCap);const progress=cap?Math.min(100,Math.round(sold/cap*100)):null;return <div key={deal.id} className="rounded-card border border-graphite-200 bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="font-semibold text-graphite-900">{deal.name}</p><p className="text-sm text-graphite-600">{deal.discountPercent}% off · {formatNaira(Number(deal.salePrice))}</p><p className="mt-1 text-xs text-graphite-500">{deal.paused?"Paused · ":"Time remaining: "}<FlashDealCountdown endsAt={deal.endsAt}/>{cap!=null&&<span> · {Math.max(0,cap-sold)} left of {cap}</span>}</p>{cap!=null&&<div className="mt-3 h-2 overflow-hidden rounded-full bg-graphite-100"><div className="h-full bg-ember-600" style={{width:`${progress}%`}}/></div>}</div><div className="flex gap-2"><button onClick={()=>void togglePause(deal)} className="rounded-card border border-graphite-300 px-3 py-2 text-sm font-semibold">{deal.paused?"Resume":"Pause"}</button><button onClick={()=>void removeDeal(deal.id)} className="rounded-card border border-graphite-300 px-3 py-2 text-sm font-semibold text-graphite-800">Remove</button></div></div></div>})}{deals.length===0&&<div className="rounded-card border border-dashed border-graphite-300 p-8 text-center text-sm text-graphite-600">No flash deals yet.</div>}</div></div>}
